export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

// HTTP utility types
export type RouteHandler = (
  req: ParsedRequest,
  res: ResponseHelper
) => Promise<void> | void;

export interface ParsedRequest {
  method: string;
  pathname: string;
  segments: string[];
  query: Record<string, string>;
  body: unknown;
}

export interface ResponseHelper {
  json: (statusCode: number, data: unknown) => void;
  error: (statusCode: number, message: string) => void;
}

export interface Route {
  method: string;
  pattern: string[]; // e.g. ["users", ":id"] or ["projects", ":id", "members"]
  handler: RouteHandler;
}

import { User, Project, Task, Comment, Notification } from "./types";

class Store {
  users: Map<string, User> = new Map();
  projects: Map<string, Project> = new Map();
  tasks: Map<string, Task> = new Map();
  comments: Map<string, Comment> = new Map();
  notifications: Map<string, Notification> = new Map();
}

export const store = new Store();

import { randomUUID } from "crypto";
import { store } from "./store";
import { Notification } from "./types";

export function generateId(): string {
  return randomUUID();
}

export function now(): string {
  return new Date().toISOString();
}

export function createNotification(userId: string, message: string): void {
  const notification: Notification = {
    id: generateId(),
    userId,
    message,
    read: false,
    createdAt: now(),
  };
  store.notifications.set(notification.id, notification);
}

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import { Route, ParsedRequest, ResponseHelper, RouteHandler } from "./types";

const routes: Route[] = [];

/**
 * Register a route.
 * Pattern segments starting with ":" are treated as named wildcards.
 * e.g. register("GET", ["users", ":id"], handler)
 */
export function register(
  method: string,
  pattern: string[],
  handler: RouteHandler
): void {
  routes.push({ method: method.toUpperCase(), pattern, handler });
}

/**
 * Attempt to match URL segments against a route pattern.
 * Returns true if they match (segments length must equal pattern length).
 */
function matchPattern(
  segments: string[],
  pattern: string[]
): boolean {
  if (segments.length !== pattern.length) return false;
  for (let i = 0; i < pattern.length; i++) {
    if (!pattern[i].startsWith(":") && pattern[i] !== segments[i]) {
      return false;
    }
  }
  return true;
}

/**
 * Read and parse the request body as JSON. Returns null on empty body.
 */
function readBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8").trim();
      if (!raw) {
        resolve(null);
        return;
      }
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

/**
 * Build a ResponseHelper that writes JSON to the ServerResponse.
 */
function makeResponseHelper(res: ServerResponse): ResponseHelper {
  return {
    json(statusCode: number, data: unknown): void {
      const body = JSON.stringify(data, null, 2);
      res.writeHead(statusCode, {
        "Content-Type": "application/json",
        "Content-Length": Buffer.byteLength(body),
      });
      res.end(body);
    },
    error(statusCode: number, message: string): void {
      this.json(statusCode, { error: message });
    },
  };
}

/**
 * Main request dispatcher. Call this from the http.createServer callback.
 */
export async function dispatch(
  req: IncomingMessage,
  res: ServerResponse
): Promise<void> {
  const helper = makeResponseHelper(res);

  let body: unknown = null;
  try {
    body = await readBody(req);
  } catch {
    helper.error(400, "Invalid JSON body");
    return;
  }

  const baseUrl = `http://localhost${req.url ?? "/"}`;
  const parsed = new URL(baseUrl);

  // Strip trailing slash and split into segments (ignore empty strings)
  const pathname = parsed.pathname.replace(/\/+$/, "") || "/";
  const segments = pathname === "/"
    ? []
    : pathname.split("/").filter((s) => s.length > 0);

  const query: Record<string, string> = {};
  parsed.searchParams.forEach((value, key) => {
    query[key] = value;
  });

  const method = (req.method ?? "GET").toUpperCase();

  const parsedRequest: ParsedRequest = {
    method,
    pathname,
    segments,
    query,
    body,
  };

  // Find matching route
  for (const route of routes) {
    if (route.method !== method) continue;
    if (!matchPattern(segments, route.pattern)) continue;

    try {
      await route.handler(parsedRequest, helper);
    } catch (err) {
      console.error("Unhandled handler error:", err);
      helper.error(500, "Internal server error");
    }
    return;
  }

  helper.error(404, `Cannot ${method} /${segments.join("/")}`);
}

import { ParsedRequest, ResponseHelper, User } from "../types";
import { store } from "../store";
import { generateId } from "../utils";

// GET /users
export function listUsers(_req: ParsedRequest, res: ResponseHelper): void {
  res.json(200, Array.from(store.users.values()));
}

// POST /users
export function createUser(req: ParsedRequest, res: ResponseHelper): void {
  const body = req.body as Record<string, unknown>;

  if (!body || typeof body.name !== "string" || typeof body.email !== "string") {
    res.error(400, "Fields 'name' and 'email' are required strings");
    return;
  }

  const name = body.name.trim();
  const email = body.email.trim();

  if (!name || !email) {
    res.error(400, "Fields 'name' and 'email' must not be empty");
    return;
  }

  // Email uniqueness check
  for (const user of store.users.values()) {
    if (user.email.toLowerCase() === email.toLowerCase()) {
      res.error(409, `A user with email '${email}' already exists`);
      return;
    }
  }

  const user: User = { id: generateId(), name, email };
  store.users.set(user.id, user);
  res.json(201, user);
}

// GET /users/:id
export function getUser(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const user = store.users.get(id);
  if (!user) {
    res.error(404, `User '${id}' not found`);
    return;
  }
  res.json(200, user);
}

// PUT /users/:id
export function updateUser(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const user = store.users.get(id);
  if (!user) {
    res.error(404, `User '${id}' not found`);
    return;
  }

  const body = req.body as Record<string, unknown>;
  if (!body) {
    res.error(400, "Request body is required");
    return;
  }

  if (body.name !== undefined) {
    if (typeof body.name !== "string" || !body.name.trim()) {
      res.error(400, "Field 'name' must be a non-empty string");
      return;
    }
    user.name = body.name.trim();
  }

  if (body.email !== undefined) {
    if (typeof body.email !== "string" || !body.email.trim()) {
      res.error(400, "Field 'email' must be a non-empty string");
      return;
    }
    const newEmail = body.email.trim();
    // Uniqueness check (exclude self)
    for (const u of store.users.values()) {
      if (u.id !== id && u.email.toLowerCase() === newEmail.toLowerCase()) {
        res.error(409, `A user with email '${newEmail}' already exists`);
        return;
      }
    }
    user.email = newEmail;
  }

  store.users.set(id, user);
  res.json(200, user);
}

// DELETE /users/:id
export function deleteUser(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  if (!store.users.has(id)) {
    res.error(404, `User '${id}' not found`);
    return;
  }
  store.users.delete(id);
  res.json(200, { message: `User '${id}' deleted` });
}

import { ParsedRequest, ResponseHelper, Project } from "../types";
import { store } from "../store";
import { generateId } from "../utils";

// GET /projects
export function listProjects(_req: ParsedRequest, res: ResponseHelper): void {
  res.json(200, Array.from(store.projects.values()));
}

// POST /projects
export function createProject(req: ParsedRequest, res: ResponseHelper): void {
  const body = req.body as Record<string, unknown>;

  if (!body || typeof body.name !== "string") {
    res.error(400, "Field 'name' is required and must be a string");
    return;
  }

  const name = body.name.trim();
  if (!name) {
    res.error(400, "Field 'name' must not be empty");
    return;
  }

  const description =
    typeof body.description === "string" ? body.description.trim() : "";

  const project: Project = {
    id: generateId(),
    name,
    description,
    memberIds: [],
  };

  store.projects.set(project.id, project);
  res.json(201, project);
}

// GET /projects/:id
export function getProject(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const project = store.projects.get(id);
  if (!project) {
    res.error(404, `Project '${id}' not found`);
    return;
  }
  res.json(200, project);
}

// PUT /projects/:id
export function updateProject(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const project = store.projects.get(id);
  if (!project) {
    res.error(404, `Project '${id}' not found`);
    return;
  }

  const body = req.body as Record<string, unknown>;
  if (!body) {
    res.error(400, "Request body is required");
    return;
  }

  if (body.name !== undefined) {
    if (typeof body.name !== "string" || !body.name.trim()) {
      res.error(400, "Field 'name' must be a non-empty string");
      return;
    }
    project.name = body.name.trim();
  }

  if (body.description !== undefined) {
    if (typeof body.description !== "string") {
      res.error(400, "Field 'description' must be a string");
      return;
    }
    project.description = body.description.trim();
  }

  store.projects.set(id, project);
  res.json(200, project);
}

// DELETE /projects/:id
export function deleteProject(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  if (!store.projects.has(id)) {
    res.error(404, `Project '${id}' not found`);
    return;
  }
  store.projects.delete(id);

  // Cascade: remove tasks belonging to this project
  for (const [taskId, task] of store.tasks.entries()) {
    if (task.projectId === id) {
      store.tasks.delete(taskId);
      // Cascade: remove comments on deleted tasks
      for (const [commentId, comment] of store.comments.entries()) {
        if (comment.taskId === taskId) {
          store.comments.delete(commentId);
        }
      }
    }
  }

  res.json(200, { message: `Project '${id}' deleted` });
}

// POST /projects/:id/members  — body: { userId }
export function addMember(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const project = store.projects.get(id);
  if (!project) {
    res.error(404, `Project '${id}' not found`);
    return;
  }

  const body = req.body as Record<string, unknown>;
  if (!body || typeof body.userId !== "string") {
    res.error(400, "Field 'userId' is required and must be a string");
    return;
  }

  const userId = body.userId.trim();
  if (!store.users.has(userId)) {
    res.error(404, `User '${userId}' not found`);
    return;
  }

  if (project.memberIds.includes(userId)) {
    res.error(409, `User '${userId}' is already a member of this project`);
    return;
  }

  project.memberIds.push(userId);
  store.projects.set(id, project);
  res.json(200, project);
}

// DELETE /projects/:id/members  — body: { userId }
export function removeMember(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const project = store.projects.get(id);
  if (!project) {
    res.error(404, `Project '${id}' not found`);
    return;
  }

  const body = req.body as Record<string, unknown>;
  if (!body || typeof body.userId !== "string") {
    res.error(400, "Field 'userId' is required and must be a string");
    return;
  }

  const userId = body.userId.trim();
  const index = project.memberIds.indexOf(userId);
  if (index === -1) {
    res.error(404, `User '${userId}' is not a member of this project`);
    return;
  }

  project.memberIds.splice(index, 1);
  store.projects.set(id, project);
  res.json(200, project);
}

import { ParsedRequest, ResponseHelper, Task, TaskStatus } from "../types";
import { store } from "../store";
import { generateId, createNotification } from "../utils";

const VALID_STATUSES: TaskStatus[] = ["todo", "in-progress", "done"];

// Allowed transitions: from -> to[]
const STATUS_TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  todo: ["in-progress"],
  "in-progress": ["done"],
  done: [],
};

function isValidStatus(s: unknown): s is TaskStatus {
  return typeof s === "string" && VALID_STATUSES.includes(s as TaskStatus);
}

// GET /tasks  (optional query: ?projectId=xxx)
export function listTasks(req: ParsedRequest, res: ResponseHelper): void {
  let tasks = Array.from(store.tasks.values());
  const { projectId } = req.query;
  if (projectId) {
    tasks = tasks.filter((t) => t.projectId === projectId);
  }
  res.json(200, tasks);
}

// POST /tasks
export function createTask(req: ParsedRequest, res: ResponseHelper): void {
  const body = req.body as Record<string, unknown>;

  if (!body || typeof body.title !== "string" || typeof body.projectId !== "string") {
    res.error(400, "Fields 'title' and 'projectId' are required strings");
    return;
  }

  const title = body.title.trim();
  const projectId = body.projectId.trim();

  if (!title || !projectId) {
    res.error(400, "Fields 'title' and 'projectId' must not be empty");
    return;
  }

  if (!store.projects.has(projectId)) {
    res.error(404, `Project '${projectId}' not found`);
    return;
  }

  const description =
    typeof body.description === "string" ? body.description.trim() : "";

  let assigneeId: string | null = null;
  if (body.assigneeId !== undefined && body.assigneeId !== null) {
    if (typeof body.assigneeId !== "string") {
      res.error(400, "Field 'assigneeId' must be a string or null");
      return;
    }
    const aid = body.assigneeId.trim();
    if (!store.users.has(aid)) {
      res.error(404, `User '${aid}' not found`);
      return;
    }
    assigneeId = aid;
  }

  let status: TaskStatus = "todo";
  if (body.status !== undefined) {
    if (!isValidStatus(body.status)) {
      res.error(400, `Field 'status' must be one of: ${VALID_STATUSES.join(", ")}`);
      return;
    }
    status = body.status;
  }

  const task: Task = {
    id: generateId(),
    title,
    description,
    status,
    assigneeId,
    projectId,
  };

  store.tasks.set(task.id, task);

  // Notify assignee if set
  if (assigneeId) {
    const assignee = store.users.get(assigneeId);
    if (assignee) {
      createNotification(
        assigneeId,
        `You have been assigned to task '${title}'`
      );
    }
  }

  res.json(201, task);
}

// GET /tasks/:id
export function getTask(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const task = store.tasks.get(id);
  if (!task) {
    res.error(404, `Task '${id}' not found`);
    return;
  }
  res.json(200, task);
}

// PUT /tasks/:id
export function updateTask(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const task = store.tasks.get(id);
  if (!task) {
    res.error(404, `Task '${id}' not found`);
    return;
  }

  const body = req.body as Record<string, unknown>;
  if (!body) {
    res.error(400, "Request body is required");
    return;
  }

  if (body.title !== undefined) {
    if (typeof body.title !== "string" || !body.title.trim()) {
      res.error(400, "Field 'title' must be a non-empty string");
      return;
    }
    task.title = body.title.trim();
  }

  if (body.description !== undefined) {
    if (typeof body.description !== "string") {
      res.error(400, "Field 'description' must be a string");
      return;
    }
    task.description = body.description.trim();
  }

  store.tasks.set(id, task);
  res.json(200, task);
}

// DELETE /tasks/:id
export function deleteTask(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  if (!store.tasks.has(id)) {
    res.error(404, `Task '${id}' not found`);
    return;
  }
  store.tasks.delete(id);

  // Cascade: remove comments on this task
  for (const [commentId, comment] of store.comments.entries()) {
    if (comment.taskId === id) {
      store.comments.delete(commentId);
    }
  }

  res.json(200, { message: `Task '${id}' deleted` });
}

// PUT /tasks/:id/status  — body: { status }
export function updateTaskStatus(
  req: ParsedRequest,
  res: ResponseHelper
): void {
  const id = req.segments[1];
  const task = store.tasks.get(id);
  if (!task) {
    res.error(404, `Task '${id}' not found`);
    return;
  }

  const body = req.body as Record<string, unknown>;
  if (!body || !isValidStatus(body.status)) {
    res.error(
      400,
      `Field 'status' is required and must be one of: ${VALID_STATUSES.join(", ")}`
    );
    return;
  }

  const newStatus = body.status;
  const allowed = STATUS_TRANSITIONS[task.status];

  if (!allowed.includes(newStatus)) {
    res.error(
      422,
      `Invalid status transition from '${task.status}' to '${newStatus}'. ` +
        `Allowed: ${allowed.length ? allowed.join(", ") : "none"}`
    );
    return;
  }

  task.status = newStatus;
  store.tasks.set(id, task);

  // Notify assignee about status change
  if (task.assigneeId) {
    createNotification(
      task.assigneeId,
      `Task '${task.title}' status changed to '${newStatus}'`
    );
  }

  res.json(200, task);
}

// PUT /tasks/:id/assign  — body: { assigneeId } (null to unassign)
export function assignTask(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const task = store.tasks.get(id);
  if (!task) {
    res.error(404, `Task '${id}' not found`);
    return;
  }

  const body = req.body as Record<string, unknown>;
  if (body === null || body === undefined) {
    res.error(400, "Request body is required");
    return;
  }

  if (!("assigneeId" in body)) {
    res.error(400, "Field 'assigneeId' is required (use null to unassign)");
    return;
  }

  const rawAssigneeId = body.assigneeId;

  if (rawAssigneeId === null) {
    task.assigneeId = null;
    store.tasks.set(id, task);
    res.json(200, task);
    return;
  }

  if (typeof rawAssigneeId !== "string" || !rawAssigneeId.trim()) {
    res.error(400, "Field 'assigneeId' must be a non-empty string or null");
    return;
  }

  const assigneeId = rawAssigneeId.trim();
  if (!store.users.has(assigneeId)) {
    res.error(404, `User '${assigneeId}' not found`);
    return;
  }

  task.assigneeId = assigneeId;
  store.tasks.set(id, task);

  // Notify new assignee
  const assignee = store.users.get(assigneeId);
  if (assignee) {
    createNotification(
      assigneeId,
      `You have been assigned to task '${task.title}'`
    );
  }

  res.json(200, task);
}

import { ParsedRequest, ResponseHelper, Comment } from "../types";
import { store } from "../store";
import { generateId, now, createNotification } from "../utils";

// GET /comments  (optional query: ?taskId=xxx)
export function listComments(req: ParsedRequest, res: ResponseHelper): void {
  let comments = Array.from(store.comments.values());
  const { taskId } = req.query;
  if (taskId) {
    comments = comments.filter((c) => c.taskId === taskId);
  }
  res.json(200, comments);
}

// POST /comments
export function createComment(req: ParsedRequest, res: ResponseHelper): void {
  const body = req.body as Record<string, unknown>;

  if (
    !body ||
    typeof body.taskId !== "string" ||
    typeof body.authorId !== "string" ||
    typeof body.body !== "string"
  ) {
    res.error(
      400,
      "Fields 'taskId', 'authorId', and 'body' are required strings"
    );
    return;
  }

  const taskId = body.taskId.trim();
  const authorId = body.authorId.trim();
  const text = body.body.trim();

  if (!taskId || !authorId || !text) {
    res.error(
      400,
      "Fields 'taskId', 'authorId', and 'body' must not be empty"
    );
    return;
  }

  const task = store.tasks.get(taskId);
  if (!task) {
    res.error(404, `Task '${taskId}' not found`);
    return;
  }

  if (!store.users.has(authorId)) {
    res.error(404, `User '${authorId}' not found`);
    return;
  }

  const comment: Comment = {
    id: generateId(),
    taskId,
    authorId,
    body: text,
    createdAt: now(),
  };

  store.comments.set(comment.id, comment);

  // Notify task assignee (if different from comment author)
  if (task.assigneeId && task.assigneeId !== authorId) {
    const author = store.users.get(authorId);
    const authorName = author ? author.name : "Someone";
    createNotification(
      task.assigneeId,
      `${authorName} commented on task '${task.title}'`
    );
  }

  // Notify project members who are not the author and not already the assignee
  const project = store.projects.get(task.projectId);
  if (project) {
    const alreadyNotified = new Set<string>();
    if (task.assigneeId) alreadyNotified.add(task.assigneeId);
    alreadyNotified.add(authorId);

    for (const memberId of project.memberIds) {
      if (!alreadyNotified.has(memberId)) {
        const author = store.users.get(authorId);
        const authorName = author ? author.name : "Someone";
        createNotification(
          memberId,
          `${authorName} commented on task '${task.title}' in project '${project.name}'`
        );
        alreadyNotified.add(memberId);
      }
    }
  }

  res.json(201, comment);
}

// GET /comments/:id
export function getComment(req: ParsedRequest, res: ResponseHelper): void {
  const id = req.segments[1];
  const comment = store.comments.get(id);
  if (!comment) {
