function show(label: string, res: ApiResponse): void {
  const ok = res.status >= 200 && res.status < 300;
  const icon = ok ? "✅" : "❌";
  console.log(`${icon} [${res.status}] ${label}`);
  console.log(JSON.stringify(res.body, null, 2));
}

